initJs:
function(container, apiUrl, tables) {
  let testExecutionTimer = null;
  let executionStartTime = null;

  // テスト履歴の再描画関数
  function renderTestHistory(rows) {
    const tbody = container.querySelector("#history-tbody");
    tbody.innerHTML = rows.map(row => `
      <tr data-id="${row.id}">
        <td>${new Date(row.作成日時).toLocaleString()}</td>
        <td>${row.予測モデルバージョン || '-'}</td>
        <td>${row.分析期間開始日 ? new Date(row.分析期間開始日).toLocaleDateString() : '-'} - ${row.分析期間終了日 ? new Date(row.分析期間終了日).toLocaleDateString() : '-'}</td>
        <td>${row.サンプル数 || '-'}</td>
        <td>${row.相関係数 ? (parseFloat(row.相関係数) * 100).toFixed(2) + '%' : '-'}</td>
        <td>${row.処理時間秒 || '-'}</td>
        <td>${row.処理時間秒 || '-'}</td>
        <td><span class="status-badge ${row.処理ステータス === '成功' ? 'success' : 'error'}">${row.処理ステータス || '完了'}</span></td>
        <td>
          <button class="action-btn secondary view-detail-btn" data-id="${row.id}">詳細</button>
          <button class="action-btn secondary delete-btn" data-id="${row.id}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 店舗チェックボックスの生成
  function renderStoreCheckboxes() {
    const storeCheckboxes = container.querySelector("#store-checkboxes");
    const stores = tables.find(t => t.tableName === "店舗マスタ")?.records || [];

    storeCheckboxes.innerHTML = stores.map(store => `
      <label>
        <input type="checkbox" class="store-checkbox" value="${store.店舗ID}">
        ${store.店舗名}
      </label>
    `).join("");
  }

  // 予測精度指標の表示
  function displayAccuracyMetrics(mape, rmse, r2, executionTime) {
    container.querySelector("#mape-value").textContent = mape !== null && mape !== undefined ? 
      (mape <= 0 || mape >= 100 ? "N/A" : mape.toFixed(2)) : "N/A";
    container.querySelector("#rmse-value").textContent = rmse !== null && rmse !== undefined ? 
      (rmse < 0 ? "算出不可" : rmse.toFixed(2)) : "N/A";
    container.querySelector("#r2-value").textContent = r2 !== null && r2 !== undefined ? 
      (r2 < 0 || r2 > 1 ? "N/A" : r2.toFixed(3)) : "N/A";
    container.querySelector("#final-execution-time").textContent = executionTime || "0";
  }

  // 実績値vs予測値グラフの描画
  function drawComparisonChart() {
    const canvas = container.querySelector("#comparison-chart");
    const ctx = canvas.getContext("2d");

    // キャンバスサイズを設定
    canvas.width = 800;
    canvas.height = 400;

    // 背景をクリア
    ctx.fillStyle = '#1a2332';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // サンプルデータ（実際の実装では API から取得）
    const actualData = [120, 135, 98, 156, 142, 118, 167, 189, 145, 132];
    const predictedData = [115, 140, 102, 150, 138, 125, 160, 185, 148, 128];
    const labels = ['1日', '2日', '3日', '4日', '5日', '6日', '7日', '8日', '9日', '10日'];

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // データの最大値・最小値を計算
    const allData = [...actualData, ...predictedData];
    const maxValue = Math.max(...allData);
    const minValue = Math.min(...allData);
    const valueRange = maxValue - minValue;

    // 実績値の線を描画
    ctx.strokeStyle = '#51cf66';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < actualData.length; i++) {
      const x = padding + (i / (actualData.length - 1)) * chartWidth;
      const y = canvas.height - padding - ((actualData[i] - minValue) / valueRange) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 予測値の線を描画
    ctx.strokeStyle = '#ff6b6b';
    ctx.lineWidth = 2;
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    for (let i = 0; i < predictedData.length; i++) {
      const x = padding + (i / (predictedData.length - 1)) * chartWidth;
      const y = canvas.height - padding - ((predictedData[i] - minValue) / valueRange) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();
    ctx.setLineDash([]);

    // 凡例の描画
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '14px sans-serif';
    ctx.fillText('実績値', canvas.width - 150, 30);
    ctx.fillText('予測値', canvas.width - 150, 50);

    ctx.strokeStyle = '#51cf66';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(canvas.width - 170, 25);
    ctx.lineTo(canvas.width - 155, 25);
    ctx.stroke();

    ctx.strokeStyle = '#ff6b6b';
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    ctx.moveTo(canvas.width - 170, 45);
    ctx.lineTo(canvas.width - 155, 45);
    ctx.stroke();
    ctx.setLineDash([]);
  }

  // モデルパラメータの表示
  function displayModelParameters() {
    const tbody = container.querySelector("#params-tbody");
    const sampleParams = [
      { name: "学習率", value: "0.001", description: "モデルの学習速度を制御" },
      { name: "隠れ層数", value: "3", description: "ニューラルネットワークの層数" },
      { name: "バッチサイズ", value: "32", description: "一度に処理するデータ数" },
      { name: "エポック数", value: "100", description: "学習の反復回数" },
      { name: "正則化係数", value: "0.01", description: "過学習を防ぐパラメータ" }
    ];

    tbody.innerHTML = sampleParams.map(param => `
      <tr>
        <td>${param.name}</td>
        <td>${param.value}</td>
        <td class="muted">${param.description}</td>
      </tr>
    `).join("");
  }

  // バリデーション関数
  function validateTestSettings() {
    const model = container.querySelector("#model-select").value;
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const category = container.querySelector("#category-select").value;
    const selectedStores = container.querySelectorAll(".store-checkbox:checked");
    const selectedDataset = container.querySelector('input[name="dataset"]:checked');

    if (!model) {
      showError("予測モデルが選択されていません");
      return false;
    }

    if (!startDate || !endDate) {
      showError("テスト期間を設定してください");
      return false;
    }

    if (new Date(endDate) < new Date(startDate)) {
      showError("終了日は開始日より後の日付を設定してください");
      return false;
    }

    if (selectedStores.length === 0) {
      showError("対象店舗を選択してください");
      return false;
    }

    if (!category) {
      showError("商品カテゴリが未選択です");
      return false;
    }

    if (!selectedDataset) {
      showError("テストデータセットが選択されていません");
      return false;
    }

    return true;
  }

  // エラーメッセージ表示
  function showError(message) {
    const existingError = container.querySelector(".error-message");
    if (existingError) existingError.remove();

    const errorDiv = document.createElement("div");
    errorDiv.className = "error-message";
    errorDiv.textContent = message;
    container.querySelector(".test-settings").appendChild(errorDiv);

    setTimeout(() => errorDiv.remove(), 5000);
  }

  // 成功メッセージ表示
  function showSuccess(message) {
    const existingSuccess = container.querySelector(".success-message");
    if (existingSuccess) existingSuccess.remove();

    const successDiv = document.createElement("div");
    successDiv.className = "success-message";
    successDiv.textContent = message;
    container.querySelector(".test-settings").appendChild(successDiv);

    setTimeout(() => successDiv.remove(), 5000);
  }

  // テスト実行のシミュレーション
  function executeModelTest() {
    if (!validateTestSettings()) return;

    const progressCard = container.querySelector("#test-progress");
    const resultsCard = container.querySelector("#test-results");
    const progressFill = container.querySelector("#progress-fill");
    const progressText = container.querySelector("#progress-text");
    const executionTimeSpan = container.querySelector("#execution-time");

    // プログレス表示
    progressCard.classList.remove("hidden");
    resultsCard.classList.add("hidden");

    executionStartTime = Date.now();
    let progress = 0;

    testExecutionTimer = setInterval(() => {
      progress += Math.random() * 15;
      if (progress > 100) progress = 100;

      progressFill.style.width = progress + "%";
      const elapsed = Math.floor((Date.now() - executionStartTime) / 1000);
      executionTimeSpan.textContent = elapsed;

      if (progress < 30) {
        progressText.textContent = "データを読み込み中...";
      } else if (progress < 60) {
        progressText.textContent = "モデルを実行中...";
      } else if (progress < 90) {
        progressText.textContent = "結果を計算中...";
      } else {
        progressText.textContent = "テストを完了中...";
      }

      if (progress >= 100) {
        clearInterval(testExecutionTimer);
        const finalTime = Math.floor((Date.now() - executionStartTime) / 1000);

        // 結果表示
        setTimeout(() => {
          progressCard.classList.add("hidden");
          resultsCard.classList.remove("hidden");

          // サンプル結果データ
          const mape = 12.5 + Math.random() * 10;
          const rmse = 15.2 + Math.random() * 5;
          const r2 = 0.85 + Math.random() * 0.1;

          displayAccuracyMetrics(mape, rmse, r2, finalTime);
          drawComparisonChart();
          displayModelParameters();

          // テスト履歴に追加
          const testResult = {
            予測モデルバージョン: container.querySelector("#model-select").value,
            分析期間開始日: container.querySelector("#start-date").value,
            分析期間終了日: container.querySelector("#end-date").value,
            サンプル数: container.querySelectorAll(".store-checkbox:checked").length,
            相関係数: (mape / 100).toString(),
            処理時間秒: finalTime,
            処理ステータス: "成功",
            作成日時: new Date().toISOString()
          };

          window.aivicApi.save(8, testResult).then(() => {
            window.aivicApi.list(8).then(renderTestHistory);
            showSuccess("モデルテストが正常に完了しました");
          });

        }, 1000);
      }
    }, 200);
  }

  // CSVエクスポート機能
  function exportTestResults() {
    const model = container.querySelector("#model-select").value;
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;

    if (!model) {
      showError("エクスポートするテスト結果がありません");
      return;
    }

    const csvData = [
      ["項目", "値"],
      ["テスト実行日時", new Date().toLocaleString()],
      ["モデル名", model],
      ["テスト期間", `${startDate} - ${endDate}`],
      ["MAPE", container.querySelector("#mape-value").textContent + "%"],
      ["RMSE", container.querySelector("#rmse-value").textContent],
      ["決定係数(R²)", container.querySelector("#r2-value").textContent],
      ["実行時間", container.querySelector("#final-execution-time").textContent + "秒"]
    ];

    const csvContent = "\uFEFF" + csvData.map(row => 
      row.map(field => `"${field}"`).join(",")
    ).join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `model_test_results_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();

    showSuccess("テスト結果をエクスポートしました");
  }

  // 初期化
  renderStoreCheckboxes();

  // 相関分析結果テーブルからテスト履歴を表示
  const correlationTable = tables.find(t => t.tableName === "相関分析結果");
  if (correlationTable) {
    renderTestHistory(correlationTable.records || []);
  }

  // 全店舗選択チェックボックス
  container.querySelector("#select-all-stores").addEventListener("change", (e) => {
    const checkboxes = container.querySelectorAll(".store-checkbox");
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // テスト実行ボタン
  container.querySelector("#btn-test-execute").addEventListener("click", executeModelTest);

  // エクスポートボタン
  container.querySelector("#btn-export-results").addEventListener("click", exportTestResults);

  // 履歴テーブルのイベント処理
  container.addEventListener("click", async (e) => {
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("このテスト履歴を削除しますか？")) return;

      const id = deleteBtn.dataset.id;
      await window.aivicApi.delete(8, id);
      const rows = await window.aivicApi.list(8);
      if (rows) renderTestHistory(rows);
      showSuccess("テスト履歴を削除しました");
    }

    const viewBtn = e.target.closest(".view-detail-btn");
    if (viewBtn) {
      showSuccess("詳細表示機能は開発中です");
    }
  });

  // 今日の日付を初期値として設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector("#start-date").value = today;
  container.querySelector("#end-date").value = today;
}
